        PageTableEntryFlags::new(
            PresentFlag::Present,
            ReadWriteFlag::ReadWrite,
            UserSupervisorFlag::Supervisor,
            PageWriteThroughFlag::NotWriteThrough,
            PageCacheDisableFlag::CacheEnabled,
            AccessedFlag::NotAccessed,
            DirtyFlag::NotDirty,
        ),
        frame,
    );
